const URL =  [
	"https://coolors.co/fcde9c-ffa552-ba5624-381d2a-c4d6b0"
	];
const STRS = [
	"PROCESSING",
	"ABCDEFGHIJKLMNOPQRSTUVWXYZ",
	"GENERATIVE",
	"TEST",
	"THEQUICKBROWNFOXJUMPSOVERTHELAZYDOG"
]
let COLS;
let Bgc = 255;
let SeedNum;
let Str;
let TypoSize;


/*
0 = blank
1-4 rectStripe
5-8 circleStripe MovePositive
9-12 circleStripe MoveNegative
*/
const H_NUM = 3;
const V_NUM = 3;
const TYPO_MAT = [
	{ name : "A", arr : [7,4,8,3,0,1,2,5,1]},
	{ name : "B", arr : [3,5,0,3,4,8,3,2,5]},
	{ name : "C", arr : [7,4,8,3,0,0,6,2,5]},	
