	{ name : "F", arr : [1,4,9,1,9,0,1,0,0]},
	{ name : "G", arr : [7,4,8,3,0,0,6,2,6]},
	{ name : "H", arr : [3,0,3,4,4,4,1,0,1]},
	{ name : "I", arr : [6,4,0,0,4,0,0,4,0]},	
	{ name : "J", arr : [0,0,4,0,0,4,6,2,5]},
	{ name : "K", arr : [4,0,5,1,1,0,2,0,8]},	
	{ name : "L", arr : [3,0,0,3,0,0,6,2,2]},
	{ name : "M", arr : [8,0,7,1,2,3,1,0,3]},	
	{ name : "N", arr : [8,0,3,1,6,3,1,0,6]},
	{ name : "O", arr : [7,4,8,3,0,1,6,2,5]},	
	{ name : "P", arr : [3,4,8,3,2,5,3,0,0]},
	{ name : "Q", arr : [7,4,8,3,0,1,6,2,6]},	
	{ name : "R", arr : [3,4,8,3,2,5,3,0,8]},
	{ name : "S", arr : [7,4,8,6,2,8,6,2,5]},
	{ name : "T", arr : [1,1,1,0,4,0,0,4,0]},
	{ name : "U", arr : [8,0,7,3,0,1,6,2,5]},	
	{ name : "V", arr : [8,0,7,3,0,5,6,5,0]},
	{ name : "W", arr : [1,0,3,1,4,3,5,0,6]},	
